import json,hashlib
from pathlib import Path
from PIL import Image,ImageDraw,ImageFont,ImageOps
ROOT=next(p for p in Path(__file__).resolve().parents if (p/'AGENTS.md').is_file())
OUT=Path(__file__).resolve().parent
qa=json.loads((OUT/'qa.json').read_text());gen=json.loads((OUT/'generation.json').read_text());palette=json.loads((OUT/'palette.json').read_text())
def filehash(p):
    h=hashlib.sha256()
    with p.open('rb') as f:
        for chunk in iter(lambda:f.read(1048576),b''):h.update(chunk)
    return h.hexdigest()
before=json.loads((OUT/'unity_before.json').read_text());after={}
for directory in ('Assets','Packages','ProjectSettings'):
    for p in sorted((ROOT/directory).rglob('*')):
        if p.is_file():after[p.relative_to(ROOT).as_posix()]=filehash(p)
protection={'changed':[p for p,h in before.items() if p in after and after[p]!=h],'removed':sorted(set(before)-set(after)),'added':sorted(set(after)-set(before)),'protected_files':len(before)}
(OUT/'unity_verification.json').write_text(json.dumps(protection,indent=2))
assert not protection['changed'] and not protection['removed'] and not protection['added'],protection
png=Image.open(ROOT/palette['source_png']).convert('RGBA')
plate=Image.open(OUT/'PNG_Approach_BoardOnly.png').convert('RGBA')
background=ImageOps.fit(png,plate.size,method=Image.Resampling.LANCZOS,centering=(.5,.5))
composite=Image.alpha_composite(background,plate);composite.save(OUT/'PNG_Approach_Composite.png')
new=Image.open(OUT/'Sand_Perspective40.png').convert('RGBA')
new_composite=Image.alpha_composite(background,new)
font=ImageFont.truetype('C:/Windows/Fonts/arial.ttf',28)
compare=Image.new('RGB',(1800,850),'#eee9e1');d=ImageDraw.Draw(compare)
for i,(im,label) in enumerate([(composite,'PNG yaklaşımı — karşılaştırma kompoziti'),(new_composite,'Yeni 3D kum — aynı tahta ve kamera')]):
    im=im.copy();im.thumbnail((890,770));compare.paste(im.convert('RGB'),(i*900+(900-im.width)//2,65+(770-im.height)//2))
    d.text((i*900+20,18),label,fill='#3e352c',font=font)
compare.save(OUT/'PNG_vs_3D.png')
sheet=Image.new('RGB',(1800,1740),'#eee9e1');d=ImageDraw.Draw(sheet)
for filename,label,col,row in [('Sand_Top.png','Üstten — 3D kum',0,0),('Sand_Perspective40.png','40° perspektif — 3D kum',1,0),('Sand_WithBlocks_Top.png','Yedi asset ile üstten',0,1),('Sand_WithBlocks.png','Yedi asset ile perspektif',1,1)]:
    im=Image.open(OUT/filename).convert('RGBA');im.thumbnail((880,795))
    base=Image.new('RGBA',im.size,(238,233,225,255));base.alpha_composite(im)
    sheet.paste(base.convert('RGB'),(col*900+(900-im.width)//2,row*870+62+(795-im.height)//2))
    d.text((col*900+20,row*870+16),label,fill='#3e352c',font=font)
sheet.save(OUT/'Sand_ReviewSheet.png')
lines=['# Block Rift — 3D kum ortamı / Blender inceleme sürümü','','Durum: Üretim ve geometri kontrolleri PASS; kullanıcı görsel onayı bekleniyor. Unity projesine aktarım veya export yapılmadı.','','## Yeni asset','','Collection: Environment_Sand_6x6. Export nesnesi: Sand_BoardTransition_6x6. Materyal: MAT_Sand_Peach_URP. Güncel AssetPreview.blend içinde ayrı Review_Sand_6x6_Empty ve Review_Sand_6x6_Fits sahneleri oluşturuldu. Eski AssetPreview sahnesine büyük kum yüzeyi bağlanmadı; diğer önizleme modellerini örtmez. Tahta ve blok referansları orijinal meshleri kullanan kopyalardır.','','Kum pivotu, Board_6x6_Frameless_Root ile aynı dünya merkezinde (8,10,0); scale=(1,1,1), rotation=(0,0,0). Tahta yerel grid pitch=1, hücre ölçüsü=0.97, hücre tepesi=-0.001, blok yerleşimi=0 aynen korundu. Kaynak tahta geometrisi veya materyalleri değiştirilmedi.','','İç sınır, gerçek yuvarlatılmış hücre zarfının .0015 dışında başlar. Kıyı yüzeyi küçük organik çöküntü ve yükseltilerle yükselerek taban çevresini sarar. Daha dışarıda çok hafif dalgalanmalar vardır. Ayrı sert kenarlık, kaya, bitki veya başka dekor meshleri eklenmedi. İnce destek yüzeyi çevresindeki kumdan daha aşağıda kaldığından üst kamera açılarında gömülü görünür; hücrelere geometrik penetrasyon yapılmaz.','','## Geometri ve mobil bütçe','','| Ölçüt | Sonuç |','|---|---:|',f"| Kaynak mesh vertex | {qa['vertices']} |",f"| Kaynak mesh triangle | {qa['triangles']} |",f"| Materyal / submesh | {qa['submeshes']} |",'| Texture | 2 × 512×512 |','| Metallic / Roughness | 0 / 0.83 |','| URP Smoothness karşılığı | 0.17 |',f"| Yaklaşık geometri veri boyutu | {qa['mesh_bytes_estimate_32_byte_vertex_16_bit_index']/1024:.2f} KiB |",f"| İki RGBA8 texture + mip varsayımı | {qa['rgba8_mipmap_memory_mib']:.2f} MiB |",'','Geometri tahmini position+normal+UV için 32 byte/vertex ve 16 bit index varsayar; import sırasında tangent, vertex bölünmesi ve başka kanallar ek boyut oluşturabilir. Texture belleği sıkıştırmasız üst düzey bir örnektir; gerçek Unity import formatı/sıkıştırması henüz ölçülmedi. Tek renderer/tek submesh temel renk geçişi için tek materyal kullanır; ışık ve shadow pass sayıları ek çizim oluşturabilir. Unity cihaz FPS veya GPU profili alınmadı.','','Kum, altı olmayan açık arazi halkasıdır: '+str(qa['topology']['boundary_edges'])+' iç/dış sınır kenarı bilinçlidir. Kapalı hacim veya Collider asseti değildir. Gizli alt yüzeyler eklenmedi. Gevşek vertex, dejenere yüzey, beklenmeyen manifold dışı kenar, ters yüz ve tutarsız winding sayıları sıfır.','','## Palet ve Unity URP materyali','','Kaynak PNG: '+palette['source_png']+'. Orta kum bölgesinin medyan sRGB tonu '+palette['median_hex']+' ölçüldü. Kum albedo haritası bu paletten deterministik olarak üretildi; kaynak PNG değiştirilmedi. Bitki/kaya gibi dekorlar yeni albedo içine kopyalanmadı. Büyük geçişler gerçek mesh, geniş renk varyasyonu ve kenar gölgelenmesi BaseColor, mikro pürüz ise küçük tangent normal haritasıyla sağlanır.','','Sand_BaseColor_512.png: URP Base Map, sRGB açık. Sand_Normal_512.png: tangent +Y, Unity Texture Type=Normal map / non-color; normal gücü .35. Materyal Base Color tint ve roughness sonradan değiştirilebilir. İki görüntü .blend içine pack edildi, ayrıca Textures/ içinde bulunur. Principled ağının Unity tarafından otomatik çevrildiği iddia edilmez; Unity URP Lit tarafında yeniden eşleme gerekecektir.','','## Geometrik doğrulama','','| Kontrol | Sonuç |','|---|---|',f"| Hücre mesh kesişimi | {qa['board_intersections']['Board_6x6_Frameless_Cells']} |",f"| Tahta destek mesh kesişimi | {qa['board_intersections']['Board_6x6_Frameless_Support']} |",f"| Üst yüzey test vertexi / kum örtmesi | {qa['top_vertices_tested']} / {qa['top_vertex_occlusions']} |",f"| İç kum kenarı — hücre mesh minimum uzaklığı | {qa['minimum_inner_edge_to_cell_mesh_distance']:.8f} |",f"| Kum Z aralığı | {qa['z_range'][0]:.8f} … {qa['z_range'][1]:.8f} |",f"| Hücre üst düzlemine minimum dikey pay | {qa['minimum_vertical_gap_to_cell_top_plane']:.8f} |",'','Hücrelerle kum arasında gerçek BVH yüzey kesişimi ve üstten ray-cast kontrolleri yapıldı. Kumun üst sınırı nominal oyun düzleminin altında, iç boşluğu hücrelerin izdüşümünün dışındadır; üst yüzeyler örtülmez. Kum oyun alanına Collider veya gameplay bileşeni eklemez. 6×6 için yedi orijinal asset tipinin tamamı, mevcut fit yerleşiminde ve toplam 205 geçerli konumda gerçek mesh BVH kontrolünden geçti: 0 kum kesişimi. Bunların 124 tanesi en dış hücrelerdeki yerleşimlerdir.','','UV_Sand_Planar sonlu ve [0,1] aralığında; split normals birim/sonlu, normal–yüz yön uyuşmazlığı 0, hesaplanan Mikk tangentler sonlu. Önceki onaylı assetlerin alt bevel normallerine dokunulmadı; önceki rapordaki asset normal bulguları bu yeni kumun doğrulamasından ayrıdır.','','## 5×5 parametreleri','','generate_sand.py içindeki build(parameters) fonksiyonu rows/columns, grid_pitch, visual_cell_size, cell_corner_radius, ring_offsets/ring_heights, arc_segments ve straight_segments ile yeniden üretilebilir. 5×5 parametreleri sayısal olarak çalıştırıldı: iç referans yarı genişlik 2.485, pitch=1 ve aynı topoloji bütçesi. Mevcut Blender dosyasında ayrı onaylı 5×5 tahta bulunmadığı için onunla fiili mesh fit testi veya yeni 5×5 sahne üretimi yapılmadı.','','## Görsel çıktılar ve PNG karşılaştırması','','Sand_Top.png, Sand_Perspective40.png, Sand_WithBlocks.png, Sand_WithBlocks_Top.png gerçek Blender renderlarıdır. Sand_ReviewSheet.png bunların paftasıdır. PNG_vs_3D.png, aynı tahta ve aynı kamera/ışıkla hazırlanmış görsel karşılaştırmadır: solda mevcut PNG merkezi kırpılıp şeffaf board-only render ile kompozit yapılmıştır; sağda gerçek 3D kum renderı vardır. Sol taraf bir Unity Game View ekran görüntüsü değildir. PNG merkez kırpımı perspektif warp ile Unity kamerasını yeniden kurma iddiası taşımaz. Referanstaki çevre dekorları 3D olarak yeniden üretilmedi.','','## Koruma ve yürütülen işlemler','','Kaydedilmemiş eski Blender oturumu Backups/OpenSession_*.blend olarak korundu. Güncel dosya açıldıktan sonra '+gen['backup']+' yedeği alındı. Önceki nesnelerin mesh/topoloji/UV/normal/materyal/Transform/Collection üyeliği parmak izleri üretim ve doğrulama sonunda aynı çıktı. Mevcut onaylı 6×6 modelleri korunmuştur; 5×5 model değiştirilmemiştir.','','prepare_textures.py paketli Python ile çalıştırıldı. generate_sand.py, verify_sand.py ve render_sand.py Blender MCP execute_blender_code ile yürütüldü. compose_report.py ile PNG kompoziti, paftalar ve bu rapor üretildi. Bütün görseller görsel QA ile incelendi.','','Assets, Packages ve ProjectSettings altındaki '+str(protection['protected_files'])+' dosyanın başlangıç/son SHA-256 manifesti karşılaştırıldı: eklenen, silinen veya değişen dosya 0. Core, prefab, script, collider, materyal veya mevcut PNG üzerinde Unity proje değişikliği yapılmadı. GDD mekanikleri etkilenmedi. Export, Unity import ve cihaz performans testi yapılmadı.','','Kullanıcı onayı sonrası Unity aktarımı ayrı bir adımdır. Üretim yalnızca Blender ve ArtProduction içindeki yeni dosyalarla sınırlıdır.']
(OUT/'REPORT.md').write_text('\n'.join(lines),encoding='utf-8')
print(json.dumps({'report':str(OUT/'REPORT.md'),'unity_protection':protection}))
